namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = new();
    public List<string> Steps { get; set; } = new();
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        // Appetizers
        new Recipe
        {
            Id = 1, Title = "Bruschetta", Category = "Appetizers",
            Description = "Classic Italian toasted bread with tomatoes and basil.",
            Ingredients = new() { "Baguette", "Tomatoes", "Fresh basil", "Garlic", "Olive oil", "Salt" },
            Steps = new() { "Slice and toast the baguette.", "Dice tomatoes and mix with chopped basil, garlic, and olive oil.", "Spoon mixture onto toasted bread and serve." }
        },
        new Recipe
        {
            Id = 2, Title = "Stuffed Mushrooms", Category = "Appetizers",
            Description = "Savory mushrooms filled with cream cheese and herbs.",
            Ingredients = new() { "Button mushrooms", "Cream cheese", "Parmesan", "Garlic", "Parsley", "Breadcrumbs" },
            Steps = new() { "Remove stems from mushrooms.", "Mix cream cheese, parmesan, garlic, and parsley.", "Fill caps with mixture, top with breadcrumbs, and bake at 375°F for 20 minutes." }
        },
        new Recipe
        {
            Id = 3, Title = "Spinach Artichoke Dip", Category = "Appetizers",
            Description = "Creamy warm dip perfect for parties.",
            Ingredients = new() { "Spinach", "Artichoke hearts", "Cream cheese", "Sour cream", "Mozzarella", "Garlic" },
            Steps = new() { "Combine all ingredients in a baking dish.", "Bake at 350°F for 25 minutes until bubbly.", "Serve with tortilla chips or bread." }
        },
        // Main Courses
        new Recipe
        {
            Id = 4, Title = "Grilled Chicken Parmesan", Category = "Main Courses",
            Description = "Juicy grilled chicken topped with marinara and melted cheese.",
            Ingredients = new() { "Chicken breasts", "Marinara sauce", "Mozzarella cheese", "Parmesan", "Italian seasoning", "Olive oil" },
            Steps = new() { "Season and grill chicken until cooked through.", "Top with marinara sauce and cheeses.", "Broil until cheese is melted and golden." }
        },
        new Recipe
        {
            Id = 5, Title = "Beef Stir Fry", Category = "Main Courses",
            Description = "Quick and flavorful beef with vegetables in soy sauce.",
            Ingredients = new() { "Beef sirloin", "Bell peppers", "Broccoli", "Soy sauce", "Ginger", "Garlic", "Rice" },
            Steps = new() { "Slice beef thinly and marinate in soy sauce and ginger.", "Stir fry vegetables in a hot wok.", "Add beef and cook until done. Serve over rice." }
        },
        new Recipe
        {
            Id = 6, Title = "Pasta Primavera", Category = "Main Courses",
            Description = "Light pasta loaded with fresh seasonal vegetables.",
            Ingredients = new() { "Penne pasta", "Zucchini", "Cherry tomatoes", "Bell pepper", "Olive oil", "Parmesan", "Basil" },
            Steps = new() { "Cook pasta according to package directions.", "Sauté vegetables in olive oil until tender.", "Toss pasta with vegetables, parmesan, and fresh basil." }
        },
        // Desserts
        new Recipe
        {
            Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich individual cakes with a molten chocolate center.",
            Ingredients = new() { "Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract" },
            Steps = new() { "Melt chocolate and butter together.", "Whisk eggs and sugar, fold in chocolate mixture and flour.", "Bake in ramekins at 425°F for 12 minutes." }
        },
        new Recipe
        {
            Id = 8, Title = "Tiramisu", Category = "Desserts",
            Description = "Classic Italian layered dessert with coffee and mascarpone.",
            Ingredients = new() { "Ladyfingers", "Mascarpone cheese", "Espresso", "Eggs", "Sugar", "Cocoa powder" },
            Steps = new() { "Whisk egg yolks with sugar, fold in mascarpone.", "Dip ladyfingers in espresso and layer in dish.", "Alternate layers of cream and ladyfingers. Dust with cocoa. Refrigerate 4 hours." }
        },
        new Recipe
        {
            Id = 9, Title = "Apple Crumble", Category = "Desserts",
            Description = "Warm spiced apples with a buttery oat topping.",
            Ingredients = new() { "Apples", "Brown sugar", "Cinnamon", "Oats", "Flour", "Butter" },
            Steps = new() { "Slice apples and toss with sugar and cinnamon.", "Mix oats, flour, sugar, and butter for topping.", "Top apples with crumble and bake at 350°F for 40 minutes." }
        },
        // Beverages
        new Recipe
        {
            Id = 10, Title = "Mango Smoothie", Category = "Beverages",
            Description = "Tropical and refreshing blended mango drink.",
            Ingredients = new() { "Mango", "Yogurt", "Milk", "Honey", "Ice" },
            Steps = new() { "Combine all ingredients in a blender.", "Blend until smooth.", "Pour into glasses and serve immediately." }
        },
        new Recipe
        {
            Id = 11, Title = "Iced Matcha Latte", Category = "Beverages",
            Description = "Creamy and earthy green tea latte served cold.",
            Ingredients = new() { "Matcha powder", "Hot water", "Milk", "Sugar", "Ice" },
            Steps = new() { "Whisk matcha with a small amount of hot water until smooth.", "Fill a glass with ice and milk.", "Pour matcha over milk and stir." }
        },
        new Recipe
        {
            Id = 12, Title = "Berry Lemonade", Category = "Beverages",
            Description = "Sweet and tart lemonade with mixed berries.",
            Ingredients = new() { "Lemons", "Mixed berries", "Sugar", "Water", "Ice", "Mint" },
            Steps = new() { "Juice lemons and muddle berries with sugar.", "Combine with water and strain.", "Serve over ice with fresh mint." }
        }
    };

    public List<Recipe> GetAllRecipes() => _recipes;

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public List<string> GetCategories() => _recipes.Select(r => r.Category).Distinct().ToList();
}

