@rendermode InteractiveServer

<div class="d-inline-block">
    <span class="fs-4">
        @for (int i = 1; i <= 5; i++)
        {
            int star = i;
            <span role="button" @onclick="() => SetRating(star)" style="cursor: pointer; color: gold;">
                @(star <= CurrentRating ? "★" : "☆")
            </span>
        }
    </span>
    @if (CurrentRating > 0)
    {
        <span class="ms-2 text-muted">(@CurrentRating / 5)</span>
    }
</div>

@code {
    private int CurrentRating { get; set; }

    private void SetRating(int rating)
    {
        CurrentRating = rating;
    }
}

@page "/recipes/{Category}"
@using RecipeCommunity.Services

<PageTitle>Recipes - @Category</PageTitle>

<h1 class="mb-4">@Category</h1>

@if (recipes.Any())
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                    </div>
                    <div class="card-footer">
                        <a href="/recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <div class="alert alert-info">No recipes found in this category.</div>
}

<a href="/" class="btn btn-outline-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    [Inject]
    private RecipeService RecipeService { get; set; } = default!;

    private List<RecipeCommunity.Models.Recipe> recipes = new();

    protected override void OnInitialized()
    {
        recipes = RecipeService.GetByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services

<PageTitle>@(recipe?.Title ?? "Recipe")</PageTitle>

@if (recipe is not null)
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/recipes/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1 class="mb-3">@recipe.Title</h1>
    <p class="lead">@recipe.Description</p>

    <div class="mb-4">
        <h5>Rate this recipe:</h5>
        <StarRating />
    </div>

    <div class="row">
        <div class="col-md-5 mb-4">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-7 mb-4">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Steps</h5></div>
                <ol class="list-group list-group-flush list-group-numbered">
                    @foreach (var step in recipe.Steps)
                    {
                        <li class="list-group-item">@step</li>
                    }
                </ol>
            </div>
        </div>
    </div>
}
else
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-outline-secondary">← Back to Home</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    [Inject]
    private RecipeService RecipeService { get; set; } = default!;

    private RecipeCommunity.Models.Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe</PageTitle>

<h1 class="mb-4">Submit a Recipe</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Recipe Submitted!</h4>
        <p>Your recipe "<strong>@title</strong>" has been submitted successfully.</p>
        <hr>
        <a href="/submit" class="btn btn-outline-success" @onclick="Reset">Submit Another</a>
    </div>
}
else
{
    <div class="card">
        <div class="card-body">
            <form @onsubmit="HandleSubmit">
                <div class="mb-3">
                    <label for="title" class="form-label">Recipe Title</label>
                    <input type="text" class="form-control" id="title" @bind="title" required />
                </div>
                <div class="mb-3">
                    <label for="ingredients" class="form-label">Ingredients (one per line)</label>
                    <textarea class="form-control" id="ingredients" rows="5" @bind="ingredients" required></textarea>
                </div>
                <div class="mb-3">
                    <label for="steps" class="form-label">Steps (one per line)</label>
                    <textarea class="form-control" id="steps" rows="5" @bind="steps" required></textarea>
                </div>
                <button type="submit" class="btn btn-primary">Submit Recipe</button>
            </form>
        </div>
    </div>
}

@code {
    private string title = string.Empty;
    private string ingredients = string.Empty;
    private string steps = string.Empty;
    private bool submitted;

    private void HandleSubmit()
    {
        if (!string.IsNullOrWhiteSpace(title))
        {
            submitted = true;
        }
    }

    private void Reset()
    {
        title = string.Empty;
        ingredients = string.Empty;
        steps = string.Empty;
        submitted = false;
    }
}

